PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS missions(mission_id TEXT PRIMARY KEY, objective TEXT, non_goals TEXT, authority_scope TEXT, risk_tier TEXT, phase TEXT, policy_version TEXT, classification_ceiling TEXT DEFAULT 'internal', created_at TEXT);
CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY AUTOINCREMENT, mission_id TEXT, etype TEXT, actor TEXT, trigger TEXT, payload_json TEXT, evidence_json TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS artifacts(artifact_id TEXT PRIMARY KEY, mission_id TEXT, kind TEXT, title TEXT, body TEXT, trust_tier INT, status TEXT, source_owner TEXT, classification TEXT, created TEXT, last_verified TEXT, discriminating INT DEFAULT 0, domain TEXT, content_hash TEXT, ingested_seq INT, quarantined INT DEFAULT 0, embedding_json TEXT);
CREATE VIRTUAL TABLE IF NOT EXISTS artifact_fts USING fts5(artifact_id UNINDEXED, title, body);
CREATE TABLE IF NOT EXISTS claims(claim_id TEXT NOT NULL, mission_id TEXT NOT NULL, statement TEXT, kind TEXT, status TEXT, mechanism_tag TEXT, corroboration TEXT, limitation TEXT, freshness TEXT, imported INT DEFAULT 0, pending_review INT DEFAULT 0, created_seq INT, updated_seq INT, PRIMARY KEY(claim_id,mission_id));
CREATE TABLE IF NOT EXISTS claim_sources(claim_id TEXT, mission_id TEXT, artifact_id TEXT, PRIMARY KEY(claim_id,mission_id,artifact_id));
CREATE TABLE IF NOT EXISTS claim_status_transitions(id INTEGER PRIMARY KEY AUTOINCREMENT, mission_id TEXT, claim_id TEXT, from_status TEXT, to_status TEXT, result TEXT, reason TEXT, evidence_json TEXT, seq INT);
CREATE TABLE IF NOT EXISTS contradictions(contradiction_id TEXT NOT NULL, mission_id TEXT NOT NULL, claim_a TEXT, claim_b TEXT, description TEXT, status TEXT, created_seq INT, resolved_seq INT, PRIMARY KEY(contradiction_id,mission_id));
CREATE TABLE IF NOT EXISTS discriminating_evidence_requirements(contradiction_id TEXT, mission_id TEXT, requirement TEXT);
CREATE TABLE IF NOT EXISTS capabilities(capability TEXT, mission_id TEXT, status TEXT, note TEXT, PRIMARY KEY(capability,mission_id));
CREATE TABLE IF NOT EXISTS gaps(gap_id INTEGER PRIMARY KEY AUTOINCREMENT, mission_id TEXT, capability TEXT, reason TEXT, layer TEXT, status TEXT, regression_test TEXT);
CREATE TABLE IF NOT EXISTS authority_rules(mission_id TEXT, action TEXT, rule TEXT, PRIMARY KEY(mission_id,action));
CREATE TABLE IF NOT EXISTS action_proposals(id INTEGER PRIMARY KEY AUTOINCREMENT, mission_id TEXT, actor TEXT, action TEXT, kind TEXT, rationale TEXT, decision TEXT, reason TEXT, seq INT);
CREATE TABLE IF NOT EXISTS action_approvals(id INTEGER PRIMARY KEY AUTOINCREMENT, mission_id TEXT, action TEXT, approver TEXT, scope TEXT, seq INT);
CREATE TABLE IF NOT EXISTS retrieval_decisions(id INTEGER PRIMARY KEY AUTOINCREMENT, mission_id TEXT, request_id TEXT, artifact_id TEXT, decision TEXT, reason TEXT, policy_version TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS retrieval_audit(request_id TEXT PRIMARY KEY, mission_id TEXT, actor_id TEXT, purpose TEXT, query TEXT, returned_json TEXT, package_hash TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS lessons(lesson_id TEXT PRIMARY KEY, source_mission TEXT, domain TEXT, lesson TEXT, transferable TEXT, regression_test TEXT);
CREATE TABLE IF NOT EXISTS regression_tests(name TEXT PRIMARY KEY, description TEXT, gap_ref TEXT);
CREATE TABLE IF NOT EXISTS revalidation_events(id INTEGER PRIMARY KEY AUTOINCREMENT, mission_id TEXT, trigger TEXT, claims_flagged TEXT, seq INT);
CREATE TABLE IF NOT EXISTS scenario_state(mission_id TEXT PRIMARY KEY, world TEXT, round INT, state_json TEXT);
CREATE TABLE IF NOT EXISTS scenario_events(id INTEGER PRIMARY KEY AUTOINCREMENT, mission_id TEXT, round INT, event TEXT);
CREATE TABLE IF NOT EXISTS scenario_actions(id INTEGER PRIMARY KEY AUTOINCREMENT, mission_id TEXT, round INT, action TEXT, result TEXT);
CREATE TABLE IF NOT EXISTS scenario_outcomes(mission_id TEXT PRIMARY KEY, outcome_json TEXT);
CREATE TABLE IF NOT EXISTS gate_rules(mission_id TEXT, action TEXT, scope_text TEXT, PRIMARY KEY(mission_id,action));
CREATE TABLE IF NOT EXISTS gate_decisions(id INTEGER PRIMARY KEY AUTOINCREMENT, mission_id TEXT, action TEXT, decision TEXT, reason TEXT, seq INT);
